guidance.correct_example:
def process(a_data: dict) -> Result[str]:
    if not isinstance(a_data, dict):
        return Result.failure(f'Expected dict, got {type(a_data).__name__}')
    name = a_data.get('name')
    if not isinstance(name, str):
        return Result.failure('name must be a string')
    return Result.success(name)

